import os
import re
import subprocess
import signal
from flask import Flask, request, jsonify

app = Flask(__name__)

@app.route('/monitor/commands', methods=['POST'])
def monitor_commands():
    data = request.get_json(silent=True)
    if not data or 'command_regex' not in data:
        return jsonify({"error": "command_regex is required"}), 400

    command_regex = data.get('command_regex')
    filter_flags = data.get('filter_flags', 'aux')

    try:
        regex = re.compile(command_regex)
    except re.error:
        return jsonify({"error": "Invalid regular expression"}), 400

    try:
        ps_command = ['ps', filter_flags]
        result = subprocess.run(ps_command, capture_output=True, text=True, timeout=10)
        if result.returncode != 0:
            return jsonify({"error": "Failed to run ps command"}), 500

        lines = result.stdout.splitlines()
        # Skip header line
        if lines and lines[0].startswith('PID'):
            lines = lines[1:]

        matching_processes = []
        for line in lines:
            parts = line.split(None, 10)
            if len(parts) < 2:
                continue
            pid_str = parts[0]
            cmd_str = parts[1] if len(parts) > 1 else ""
            try:
                pid = int(pid_str)
            except ValueError:
                continue

            if regex.search(cmd_str):
                matching_processes.append({
                    "processId": pid,
                    "processString": cmd_str
                })

        return jsonify(matching_processes), 200

    except subprocess.TimeoutExpired:
        return jsonify({"error": "Command timed out"}), 500
    except Exception as e:
        return jsonify({"error": str(e)}), 500

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=5000)
